import csv
cool='f0c17382-5dc5-5762-aef6-7d433ca8d7bb'
temp='f9990edd-406b-5118-8fc2-62ecc998fe86'

def load(ts):
    d={}
    with open(VALUES_CSV) as f:
        for r in csv.DictReader(f):
            if r['timeseries_id']==ts:
                d[r['timestamp']]=float(r['value'])
    return d

ct=load(temp)
cs=load(cool)

def mean_dev(date):
    vals=[]
    for ts,v in ct.items():
        if ts.startswith(date):
            hr=ts[11:13]
            if '08'<=hr<='18':
                if ts in cs:
                    vals.append(v-cs[ts])
    return sum(vals)/len(vals), len(vals)

